using System.Text.Json; using Microsoft.AspNetCore.Authorization; using AshkanCMS.Data; using AshkanCMS.Models; using AshkanCMS.Services; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.Rendering; using Microsoft.EntityFrameworkCore;
namespace AshkanCMS.Areas.Admin.Controllers; [Area("Admin"),Authorize]
public class PostsController(AppDbContext db,SlugService slug):Controller{public async Task<IActionResult> Index(string? q){var x=db.Posts.Include(p=>p.Category).AsQueryable();if(!string.IsNullOrWhiteSpace(q))x=x.Where(p=>p.Title.Contains(q));return View(await x.OrderByDescending(p=>p.CreatedAt).ToListAsync());} public async Task<IActionResult>Create(){ViewBag.Categories=new SelectList(await db.Categories.ToListAsync(),"Id","Name");return View(new Post());}[HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult>Create(Post p){if(!ModelState.IsValid){ViewBag.Categories=new SelectList(await db.Categories.ToListAsync(),"Id","Name");return View(p);}p.Slug=slug.Make(string.IsNullOrWhiteSpace(p.Slug)?p.Title:p.Slug);if(p.Status==ContentStatus.Published)p.PublishedAt=DateTime.UtcNow;db.Add(p);await db.SaveChangesAsync();return RedirectToAction(nameof(Index));} public async Task<IActionResult>Edit(int id){var p=await db.Posts.FindAsync(id);if(p==null)return NotFound();ViewBag.Categories=new SelectList(await db.Categories.ToListAsync(),"Id","Name",p.CategoryId);return View(p);}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Edit(int id,Post p){if(id!=p.Id)return NotFound();var current=await db.Posts.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id);if(current==null)return NotFound();db.Revisions.Add(new ContentRevision{PostId=id,Title=current.Title,Body=current.Body,CreatedBy=User.Identity?.Name??"system"});p.Slug=slug.Make(string.IsNullOrWhiteSpace(p.Slug)?p.Title:p.Slug);if(p.Status==ContentStatus.Published && p.PublishedAt==null)p.PublishedAt=DateTime.UtcNow;db.Update(p);db.Notifications.Add(new NotificationItem{Title="Post updated",Message=$"{p.Title} was updated by {User.Identity?.Name??"editor"}."});await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Delete(int id){var p=await db.Posts.FindAsync(id);if(p!=null){db.TrashItems.Add(new TrashItem{EntityType="Post",EntityId=p.Id,Title=p.Title,PayloadJson=JsonSerializer.Serialize(p),DeletedBy=User.Identity?.Name??"system"});db.Remove(p);await db.SaveChangesAsync();}return RedirectToAction(nameof(Index));}}
